def newton(f, df, x0, tol=1e-10, max_iter=100):
    x = x0
    for k in range(max_iter):
        df_x = df(x)
        if abs(df_x) < 1e-14:
            raise RuntimeError(
                f"Derivada casi cero en iteración {k}, x={x}"
            )
        x_nuevo = x - f(x) / df_x
        error = abs(x_nuevo - x)
        if error < tol:
            return x_nuevo, k
        x = x_nuevo
    raise RuntimeError(f"No convergió en {max_iter} iteraciones")

f = lambda x: x**3 - x - 2
df = lambda x: 3*x**2 - 1

try:
    raiz, iters = newton(f, df, 1.5)
    print(f"Raíz: {raiz:.10f} en {iters} iteraciones")
except RuntimeError as e:
    print(f"Error: {e}")

def biseccion(f, a, b, tol=1e-8, max_iter=100):
    if a >= b:
        raise ValueError(f"a debe ser menor que b: a={a}, b={b}")

    fa = f(a)
    fb = f(b)
    if fa * fb >= 0:
        raise ValueError(
            f"Bolzano no se cumple: f(a)={fa}, f(b)={fb}"
        )

    for k in range(max_iter):
        c = (a + b) / 2
        fc = f(c)
        if abs(fc) < tol or (b - a) / 2 < tol:
            return c, k
        if fa * fc < 0:
            b = c
            fb = fc
        else:
            a = c
            fa = fc
    raise RuntimeError(f"No convergió en {max_iter} iteraciones")

f = lambda x: x**3 - x - 2
try:
    raiz, iters = biseccion(f, 1, 2)
    print(f"Raíz: {raiz:.10f}, iteraciones: {iters}")
except (ValueError, RuntimeError) as e:
    print(f"Error: {e}")
